{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Transit Gateway default route table association enabled",
      "resource": "aws_ec2_transit_gateway.pass2",
      "severity": "MEDIUM",
      "explanation": "The default route table association setting is omitted and therefore defaults to enabled, causing new attachments to be associated automatically and potentially permitting unintended network connectivity."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Transit Gateway default route propagation enabled",
      "resource": "aws_ec2_transit_gateway.pass2",
      "severity": "MEDIUM",
      "explanation": "The default route table propagation setting is omitted and therefore defaults to enabled, allowing attachment routes to propagate automatically instead of being explicitly controlled."
    }
  ],
  "patched_code": "resource \"aws_ec2_transit_gateway\" \"pass2\" {\n  description                     = \"sato\"\n  auto_accept_shared_attachments = \"disable\"\n  default_route_table_association = \"disable\"\n  default_route_table_propagation = \"disable\"\n}\n",
  "fix_summary": "Disabled automatic default route table association and propagation so Transit Gateway attachment routing must be configured explicitly."
}
